CREATE TYPE "SourceKind" AS ENUM ('GREENHOUSE','LEVER','ASHBY','COMPANY_SITE','MANUAL');
CREATE TYPE "WorkplaceType" AS ENUM ('REMOTE','HYBRID','ONSITE');
CREATE TYPE "JobStatus" AS ENUM ('FOUND','VERIFIED','QUALIFIED','REVIEWING','APPLIED','FOLLOWUP','INTERVIEW','OFFER','REJECTED','EXPIRED','CLOSED');
CREATE TYPE "MatchClass" AS ENUM ('A','B','C','D');
CREATE TYPE "AppStatus" AS ENUM ('PLANNED','PREPARED','NEEDS_REVIEW','NEEDS_HUMAN','SUBMITTED','FOLLOWUP','INTERVIEW','OFFER','REJECTED','WITHDRAWN');
CREATE TYPE "SubmissionMode" AS ENUM ('REVIEW','ASSISTED','AUTOMATIC');
CREATE TYPE "FollowupStatus" AS ENUM ('PENDING','SENT','COMPLETED','CANCELLED');
CREATE TABLE "SourceConfig" ("id" TEXT PRIMARY KEY,"kind" "SourceKind" NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT true,"settings" JSONB,"lastRunAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Job" ("id" TEXT PRIMARY KEY,"sourceConfigId" TEXT,"source" "SourceKind" NOT NULL,"externalId" TEXT NOT NULL,"title" TEXT NOT NULL,"company" TEXT NOT NULL,"location" TEXT,"workplaceType" "WorkplaceType","employmentType" TEXT,"salaryMin" INTEGER,"salaryMax" INTEGER,"salaryCurrency" TEXT DEFAULT 'USD',"url" TEXT NOT NULL,"description" TEXT NOT NULL,"postedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"verifiedAt" TIMESTAMP(3),"status" "JobStatus" NOT NULL DEFAULT 'FOUND',"score" INTEGER,"matchClass" "MatchClass","scoreProof" JSONB,"fingerprint" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "ResumeVersion" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"focus" TEXT NOT NULL,"storageRef" TEXT,"contentHash" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "TailoredResume" ("id" TEXT PRIMARY KEY,"jobId" TEXT NOT NULL,"resumeVersionId" TEXT NOT NULL,"headline" TEXT NOT NULL,"summary" TEXT NOT NULL,"selectedClaims" JSONB NOT NULL,"keywordCoverage" JSONB NOT NULL,"content" TEXT NOT NULL,"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Application" ("id" TEXT PRIMARY KEY,"jobId" TEXT NOT NULL,"resumeVersionId" TEXT,"tailoredResumeId" TEXT,"status" "AppStatus" NOT NULL DEFAULT 'PLANNED',"submissionMode" "SubmissionMode" NOT NULL DEFAULT 'REVIEW',"externalRef" TEXT,"appliedAt" TIMESTAMP(3),"followupAt" TIMESTAMP(3),"notes" TEXT,"answersSnapshot" JSONB,"blockers" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Followup" ("id" TEXT PRIMARY KEY,"applicationId" TEXT NOT NULL,"dueAt" TIMESTAMP(3) NOT NULL,"channel" TEXT NOT NULL DEFAULT 'EMAIL',"status" "FollowupStatus" NOT NULL DEFAULT 'PENDING',"template" TEXT,"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"actor" TEXT NOT NULL DEFAULT 'SYSTEM',"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "SourceConfig_kind_slug_key" ON "SourceConfig"("kind","slug");
CREATE UNIQUE INDEX "Job_source_externalId_key" ON "Job"("source","externalId");
CREATE INDEX "Job_status_score_idx" ON "Job"("status","score");CREATE INDEX "Job_company_title_idx" ON "Job"("company","title");CREATE INDEX "Job_fingerprint_idx" ON "Job"("fingerprint");
CREATE UNIQUE INDEX "ResumeVersion_name_key" ON "ResumeVersion"("name");CREATE INDEX "TailoredResume_jobId_idx" ON "TailoredResume"("jobId");
CREATE UNIQUE INDEX "Application_jobId_key" ON "Application"("jobId");CREATE INDEX "Application_status_followupAt_idx" ON "Application"("status","followupAt");
CREATE INDEX "Followup_status_dueAt_idx" ON "Followup"("status","dueAt");CREATE INDEX "AuditLog_entityType_entityId_idx" ON "AuditLog"("entityType","entityId");CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
ALTER TABLE "Job" ADD CONSTRAINT "Job_sourceConfigId_fkey" FOREIGN KEY ("sourceConfigId") REFERENCES "SourceConfig"("id") ON DELETE SET NULL;
ALTER TABLE "TailoredResume" ADD CONSTRAINT "TailoredResume_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE;ALTER TABLE "TailoredResume" ADD CONSTRAINT "TailoredResume_resumeVersionId_fkey" FOREIGN KEY ("resumeVersionId") REFERENCES "ResumeVersion"("id");
ALTER TABLE "Application" ADD CONSTRAINT "Application_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE;ALTER TABLE "Application" ADD CONSTRAINT "Application_resumeVersionId_fkey" FOREIGN KEY ("resumeVersionId") REFERENCES "ResumeVersion"("id");ALTER TABLE "Application" ADD CONSTRAINT "Application_tailoredResumeId_fkey" FOREIGN KEY ("tailoredResumeId") REFERENCES "TailoredResume"("id");
ALTER TABLE "Followup" ADD CONSTRAINT "Followup_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "Application"("id") ON DELETE CASCADE;
